import pandas as pd

def compute_monthly_revenue(df):
    df = df.copy()
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['year_month'] = df['order_date'].dt.to_period('M')
    return df.groupby('year_month', as_index=True)['revenue'].sum()

import pandas as pd

def filter_top_customers(df, n=10):
    unique = df.drop_duplicates(subset=['customer_id'])
    sorted_df = unique.sort_values('total_spend', ascending=False)
    return sorted_df.head(n)

import json

def export_analytics_summary(df, output_path):
    summary = {
        'total_revenue': df['revenue'].sum(),
        'avg_order_value': df['revenue'].mean(),
        'unique_customers': df['customer_id'].nunique()
    }
    with open(output_path, 'w') as f:
        json.dump(summary, f, indent=2)
